:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:20:\"Contact Form 7 6.2.4\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:55:\"https://contactform7.com/2026/10/29/contact-form-7-624/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 29 Oct 2026 10:22:10 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:2:{i:0;a:5:{s:4:\"data\";s:8:\"Releases\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:8:\"Security\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:33:\"https://contactform7.com/?p=93091\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:540:\"Contact Form 7 version 6.2.4 is now available. This is a minor update release that includes several security fixes and enhancements. While the vulnerability is seen only in Contact Form 7 6.2 to 6.2.3, since the security enhancements apply to all versions of the plugin, we recommend upgrading to 6.2.4 for all users. Outline of &#8230; <a href=\"https://contactform7.com/2026/10/29/contact-form-7-624/\" class=\"more-link\">Continue reading <span class=\"screen-reader-text\">Contact Form 7 6.2.4</span> <span class=\"meta-nav\">&#8594;</span></a>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Takayuki Miyoshi\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:4951:\"\n<p class=\"wp-block-paragraph\">Contact Form 7 version 6.2.4 is now available. This is a minor update release that includes several security fixes and enhancements. While the vulnerability is seen only in Contact Form 7 6.2 to 6.2.3, since the security enhancements apply to all versions of the plugin, we recommend upgrading to 6.2.4 for all users.</p>\n\n\n\n<span id=\"more-93091\"></span>\n\n\n\n<h4 id=\"outline-of-the-issue\" class=\"wp-block-heading\">Outline of the issue</h4>\n\n\n\n<p class=\"wp-block-paragraph\">The issue is an unauthenticated arbitrary file upload. Attackers can leverage multiple flaws in Contact Form 7 6.2 to 6.2.3, in combination, to upload files that should normally be blocked by validation logic and keep files that should normally be removed immediately after submission.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Theoretically, all forms that have file uploading fields and are hosted on an HTTP server configured to list directory contents publicly can be a target.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This issue was detected by Shinya Murakami and Jakub Herman, and reported via <a href=\"https://wpscan.com/\">WPScan</a>.</p>\n\n\n\n<h4 id=\"side-effects\" class=\"wp-block-heading\">Side effects</h4>\n\n\n\n<p class=\"wp-block-paragraph\">To enhance security, we needed to introduce changes that could affect certain use cases.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><code>wpcf7_antiscript_file_name()</code>, which sanitizes a file name that can be recognized as an executable script file, now uses a safelist of file extensions in place of the previous unsafelist. If a file with an extension that is not included in the safelist is uploaded, <code>wpcf7_antiscript_file_name()</code> automatically converts the extension part into a safe alternative.</p>\n\n\n\n<p class=\"wp-block-paragraph\">By default, the safelist includes the following file extensions:</p>\n\n\n<div class=\"wp-block-syntaxhighlighter-code \"><pre class=\"brush: php; title: ; notranslate\">\n&#x5B;&quot;3gp&quot;,&quot;3gpp&quot;,&quot;3g2&quot;,&quot;3gp2&quot;,&quot;aac&quot;,&quot;flac&quot;,&quot;mid&quot;,&quot;midi&quot;,&quot;mp3&quot;,&quot;m4a&quot;,&quot;m4b&quot;,&quot;ogg&quot;,&quot;oga&quot;,&quot;wav&quot;,&quot;x-wav&quot;,&quot;mka&quot;,&quot;wax&quot;,&quot;wma&quot;,&quot;ra&quot;,&quot;ram&quot;,&quot;avi&quot;,&quot;divx&quot;,&quot;mp4&quot;,&quot;m4v&quot;,&quot;mpeg&quot;,&quot;mpg&quot;,&quot;mpe&quot;,&quot;ogv&quot;,&quot;mov&quot;,&quot;qt&quot;,&quot;webm&quot;,&quot;flv&quot;,&quot;mkv&quot;,&quot;asf&quot;,&quot;asx&quot;,&quot;wm&quot;,&quot;wmv&quot;,&quot;wmx&quot;,&quot;avif&quot;,&quot;bmp&quot;,&quot;gif&quot;,&quot;heic&quot;,&quot;heics&quot;,&quot;heif&quot;,&quot;heifs&quot;,&quot;jpg&quot;,&quot;jpeg&quot;,&quot;jpe&quot;,&quot;png&quot;,&quot;tiff&quot;,&quot;tif&quot;,&quot;webp&quot;,&quot;ico&quot;,&quot;pdf&quot;,&quot;txt&quot;]\n</pre></div>\n\n\n<p class=\"wp-block-paragraph\">You can customize this list using the <code>wpcf7_file_extension_safelist</code> filter hook, like the following:</p>\n\n\n<div class=\"wp-block-syntaxhighlighter-code \"><pre class=\"brush: php; title: ; notranslate\">\nadd_filter( &#039;wpcf7_file_extension_safelist&#039;, function ( $safelist ) {\n	return array_merge( $safelist,  &#x5B;&#039;zip&#039;] ); // Adding .zip\n} );\n</pre></div>\n\n\n<p class=\"wp-block-paragraph\">Another change was made to <code>wpcf7_unship_uploaded_file()</code>; its second <code>$options</code> argument is now mandatory, and a third <code>$uploaded_files</code> argument has been added. Although this function is not for daily use, and most users don’t even know it, if by any chance you call <code>wpcf7_unship_uploaded_file()</code> in your code, don’t forget to change the arguments.</p>\n\n\n\n<h4 id=\"major-changes\" class=\"wp-block-heading\">Major changes</h4>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Functions-PHP: Upgraded to 1.1.0.</li>\n\n\n\n<li>FormDataTree-PHP: Upgraded to 2.0.9.</li>\n\n\n\n<li>SWV-PHP: Upgraded to 2.0.8.</li>\n\n\n\n<li>Introduces the <code>wpcf7_file_extension_safelist()</code> function and the <code>wpcf7_file_extension_safelist</code> filter hook.</li>\n\n\n\n<li>Improves <code>wpcf7_antiscript_file_name()</code> with file extension safelist.</li>\n\n\n\n<li>Applies <code>wp_scrub_utf8()</code> to a target text before a regular expression pattern with the <code>u</code> (UTF-8) modifier is applied to it.</li>\n\n\n\n<li>Improves <code>wpcf7_unship_uploaded_file()</code> with the new third parameter (<code>$uploaded_files</code>) that is passed as a reference.</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">You can browse the complete list of changes on <a href=\"https://github.com/rocklobster-in/contact-form-7/compare/v6.2.3...v6.2.4\">GitHub</a>.</p>\n\n\n<p><strong>Requires:</strong> WordPress 7.1 or higher<br />\n<strong>Tested up to:</strong> WordPress 7.1.4</p>\n<p><strong><a href=\"https://wordpress.org/plugins/contact-form-7/\">&raquo; Download Contact Form 7 plugin from WordPress.org</a></strong></p>\n\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"93091\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:1;a:6:{s:4:\"data\";s:57:\"\n		\n		\n		\n		\n		\n				\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:20:\"Contact Form 7 6.2.3\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:55:\"https://contactform7.com/2026/10/21/contact-form-7-623/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 21 Oct 2026 08:44:52 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Releases\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:33:\"https://contactform7.com/?p=93068\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:194:\"Contact Form 7 version 6.2.3 is now available. This is a minor update release that includes a few bug fixes and improvements. Major changes You can browse the complete list of changes on GitHub.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Takayuki Miyoshi\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:998:\"\n<p class=\"wp-block-paragraph\">Contact Form 7 version 6.2.3 is now available. This is a minor update release that includes a few bug fixes and improvements.</p>\n\n\n\n<span id=\"more-93068\"></span>\n\n\n\n\n\n\n<h4 id=\"major-changes\" class=\"wp-block-heading\">Major changes</h4>\n\n\n\n<ul class=\"wp-block-list\">\n<li>SWV-JS: Updates the package to v2.1.4, which fixes a timezone-related bug.</li>\n\n\n\n<li>Dashboard: Shows a notice when a new version of the plugin is available.</li>\n\n\n\n<li>REST API: Fixes a bug that caused by unnecessary <code>static</code> keywords.</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">You can browse the complete list of changes on <a href=\"https://github.com/rocklobster-in/contact-form-7/compare/v6.2.2...v6.2.3\">GitHub</a>.</p>\n\n\n<p><strong>Requires:</strong> WordPress 7.1 or higher<br />\n<strong>Tested up to:</strong> WordPress 7.1.3</p>\n<p><strong><a href=\"https://wordpress.org/plugins/contact-form-7/\">&raquo; Download Contact Form 7 plugin from WordPress.org</a></strong></p>\n\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"93068\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:2;a:6:{s:4:\"data\";s:57:\"\n		\n		\n		\n		\n		\n				\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:38:\"Announcement of plugin privacy notices\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:75:\"https://contactform7.com/2026/10/16/announcement-of-plugin-privacy-notices/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 16 Oct 2026 07:28:06 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:12:\"Announcement\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:33:\"https://contactform7.com/?p=93024\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:590:\"We published the plugin privacy notices page, which outlines how the plugin handles users&#8217; personal data. Every site must have a privacy policy. Contact Form 7 manages contact forms; these forms are closely linked to privacy because almost every submission includes personal data. So, if you have a contact form on your site, you must &#8230; <a href=\"https://contactform7.com/2026/10/16/announcement-of-plugin-privacy-notices/\" class=\"more-link\">Continue reading <span class=\"screen-reader-text\">Announcement of plugin privacy notices</span> <span class=\"meta-nav\">&#8594;</span></a>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Takayuki Miyoshi\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:1404:\"\n<p class=\"wp-block-paragraph\">We published the <a href=\"https://contactform7.com/plugin-privacy-notices/\" data-type=\"link\" data-id=\"https://contactform7.com/plugin-privacy-notices/\">plugin privacy notices</a> page, which outlines how the plugin handles users&#8217; personal data.</p>\n\n\n\n<span id=\"more-93024\"></span>\n\n\n\n<h4 class=\"wp-block-heading\">Every site must have a privacy policy.</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Contact Form 7 manages contact forms; these forms are closely linked to privacy because almost every submission includes personal data. So, if you have a contact form on your site, you must have a privacy policy. When you compile a privacy policy for your site, please feel free to use the <a href=\"https://contactform7.com/plugin-privacy-notices/\" data-type=\"link\" data-id=\"https://contactform7.com/plugin-privacy-notices/\">plugin privacy notices</a> as a reference.</p>\n\n\n\n<p class=\"wp-block-paragraph\">That said, it will be difficult to draft a privacy policy unless you are a legal professional. In writing the privacy notices, we received helpful advice from Termageddon, a company that helps website owners create privacy policies. If you don&#8217;t know someone to ask about legal documentation for websites, we recommend <a href=\"https://termageddon.com/\" data-type=\"link\" data-id=\"https://termageddon.com/\">Termageddon</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\"></p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"93024\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:3;a:6:{s:4:\"data\";s:57:\"\n		\n		\n		\n		\n		\n				\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:20:\"Contact Form 7 6.2.2\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:55:\"https://contactform7.com/2026/10/11/contact-form-7-622/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sun, 11 Oct 2026 07:51:17 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Releases\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:33:\"https://contactform7.com/?p=92970\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:167:\"Contact Form 7 version 6.2.2 is now available. This is a minor update release including a bug fix. Major changes You can browse the complete list of changes on GitHub.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Takayuki Miyoshi\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:841:\"\n<p class=\"wp-block-paragraph\">Contact Form 7 version 6.2.2 is now available. This is a minor update release including a bug fix.</p>\n\n\n\n<span id=\"more-92970\"></span>\n\n\n\n\n\n\n<h4 id=\"major-changes\" class=\"wp-block-heading\">Major changes</h4>\n\n\n\n<ul class=\"wp-block-list\">\n<li>SWV-PHP: Applies <code>wp_unslash()</code> to <code>$_POST</code> to avoid false-positive in the <code>enum</code> rule.</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">You can browse the complete list of changes on <a href=\"https://github.com/rocklobster-in/contact-form-7/compare/v6.2.1...v6.2.2\">GitHub</a>.</p>\n\n\n<p><strong>Requires:</strong> WordPress 7.1 or higher<br />\n<strong>Tested up to:</strong> WordPress 7.1.3</p>\n<p><strong><a href=\"https://wordpress.org/plugins/contact-form-7/\">&raquo; Download Contact Form 7 plugin from WordPress.org</a></strong></p>\n\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"92970\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:4;a:6:{s:4:\"data\";s:57:\"\n		\n		\n		\n		\n		\n				\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:47:\"Follow the recommendation (not the requirement)\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:82:\"https://contactform7.com/2026/10/10/follow-the-recommendation-not-the-requirement/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sat, 10 Oct 2026 08:52:16 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Opinions\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:33:\"https://contactform7.com/?p=92967\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:570:\"Contact Form 7 6.2 raised its PHP requirement from 7.4 to 8.3. This decision was made based on our policy that our products only support PHP versions that WordPress recommends. Some weeks ago, I read a post on the Make WordPress Core blog that was a note from an informal conversation held at WordCamp US &#8230; <a href=\"https://contactform7.com/2026/10/10/follow-the-recommendation-not-the-requirement/\" class=\"more-link\">Continue reading <span class=\"screen-reader-text\">Follow the recommendation (not the requirement)</span> <span class=\"meta-nav\">&#8594;</span></a>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Takayuki Miyoshi\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:3285:\"\n<p class=\"wp-block-paragraph\"><a href=\"https://contactform7.com/2026/10/06/contact-form-7-620/\" data-type=\"post\" data-id=\"92937\">Contact Form 7 6.2</a> raised its PHP requirement from 7.4 to 8.3. This decision was made based on <a href=\"https://contactform7.com/2025/12/02/wordpress-support-policy-revised/\" data-type=\"link\" data-id=\"https://contactform7.com/2025/12/02/wordpress-support-policy-revised/\">our policy</a> that our products only support PHP versions that WordPress recommends.</p>\n\n\n\n<span id=\"more-92967\"></span>\n\n\n\n\n\n\n<p class=\"wp-block-paragraph\">Some weeks ago, I read a <a href=\"https://make.wordpress.org/core/2026/09/03/wordcamp-us-2026-php-conversation/\" data-type=\"link\" data-id=\"https://make.wordpress.org/core/2026/09/03/wordcamp-us-2026-php-conversation/\">post on the Make WordPress Core blog</a> that was a note from an informal conversation held at WordCamp US 2026. The part I found the most interesting was:</p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\">Many in the PHP community don’t consider WordPress developers to be “PHP developers.” Part of this is due to WordPress being seen as dragging PHP backwards because of its backwards compatibility commitments.</p>\n</blockquote>\n\n\n\n<p class=\"wp-block-paragraph\">It also made me a bit sad. WordPress developers are PHP developers, of course. And WordPress has committed to backward compatibility so seriously because that is the responsibility of the most popular CMS, which sustains a tremendous number of PHP sites.</p>\n\n\n\n<p class=\"wp-block-paragraph\">That said, as mentioned in the post, 18% of WordPress sites still run PHP 7.4, which had its end of life <a href=\"https://www.php.net/eol.php#:~:text=7%2E4\" data-type=\"link\" data-id=\"https://www.php.net/eol.php#:~:text=7%2E4\">4 years ago</a>. Those sites are facing unimaginably serious security risks. However, until this percentage sinks below 5%, it will be difficult for WordPress to raise its PHP requirement from the current 7.4. On the other hand, if WordPress continued to support PHP 7.4, it could disincentivize users from upgrading PHP.</p>\n\n\n\n<p class=\"wp-block-paragraph\">It seems like a chicken-and-egg situation.</p>\n\n\n\n\n\n\n<h4 class=\"wp-block-heading\">Pave the road to allow WordPress to raise PHP requirement</h4>\n\n\n\n<p class=\"wp-block-paragraph\">I want to call on colleague plugin developers to take concerted action to raise the PHP requirement of our plugins. By joining this action, you can enjoy benefits such as:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>You can use cutting-edge techniques supported by the latest PHP versions.</li>\n\n\n\n<li>Narrowing the PHP support range reduces your testing and user support burden.</li>\n\n\n\n<li>It also minimizes the attack surface you have to protect.</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">Plugins can decide their PHP support range more flexibly than the WordPress core can, because each plugin’s user base is far smaller than the core’s. And if popular plugins raise their PHP requirements, that can incentivize their users to upgrade PHP on their sites. The number of sites that use outdated PHP versions will decrease. Ultimately, it will make it easier for WordPress to raise its PHP requirement.</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"92967\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:5;a:6:{s:4:\"data\";s:57:\"\n		\n		\n		\n		\n		\n				\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:20:\"Contact Form 7 6.2.1\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:55:\"https://contactform7.com/2026/10/08/contact-form-7-621/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 08 Oct 2026 08:59:57 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Releases\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:33:\"https://contactform7.com/?p=92952\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:175:\"Contact Form 7 version 6.2.1 is now available. This is a minor update release including some improvements. Major changes You can browse the complete list of changes on GitHub.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Takayuki Miyoshi\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:810:\"\n<p class=\"wp-block-paragraph\">Contact Form 7 version 6.2.1 is now available. This is a minor update release including some improvements.</p>\n\n\n\n<span id=\"more-92952\"></span>\n\n\n\n\n\n\n<h4 id=\"major-changes\" class=\"wp-block-heading\">Major changes</h4>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Replaces a relative path to an absolute path in <code>require</code> expressions.</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">You can browse the complete list of changes on <a href=\"https://github.com/rocklobster-in/contact-form-7/compare/v6.2.0...v6.2.1\">GitHub</a>.</p>\n\n\n<p><strong>Requires:</strong> WordPress 7.1 or higher<br />\n<strong>Tested up to:</strong> WordPress 7.1.3</p>\n<p><strong><a href=\"https://wordpress.org/plugins/contact-form-7/\">&raquo; Download Contact Form 7 plugin from WordPress.org</a></strong></p>\n\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"92952\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:6;a:6:{s:4:\"data\";s:57:\"\n		\n		\n		\n		\n		\n				\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:18:\"Contact Form 7 6.2\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:55:\"https://contactform7.com/2026/10/06/contact-form-7-620/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 06 Oct 2026 01:26:27 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Releases\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:33:\"https://contactform7.com/?p=92937\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:547:\"Contact Form 7 version 6.2 is now available. This is a major update including significant changes. Check the 6.2-RC announcement post if you&#8217;re interested in the changes made in 6.2. We recommend upgrading to 6.2 for all users. Note: Contact Form 7 6.2 requires WordPress 7.1+ and PHP 8.3+, in accordance with our WordPress support &#8230; <a href=\"https://contactform7.com/2026/10/06/contact-form-7-620/\" class=\"more-link\">Continue reading <span class=\"screen-reader-text\">Contact Form 7 6.2</span> <span class=\"meta-nav\">&#8594;</span></a>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Takayuki Miyoshi\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:1872:\"\n<p class=\"wp-block-paragraph\">Contact Form 7 version 6.2 is now available. This is a major update including significant changes. Check the <a href=\"https://contactform7.com/2026/09/22/contact-form-7-62-rc/\" data-type=\"link\" data-id=\"https://contactform7.com/2026/09/22/contact-form-7-62-rc/\">6.2-RC announcement post</a> if you&#8217;re interested in the changes made in 6.2. We recommend upgrading to 6.2 for all users.</p>\n\n\n\n<span id=\"more-92937\"></span>\n\n\n\n<p class=\"wp-block-paragraph\">Note: Contact Form 7 6.2 requires WordPress 7.1+ and PHP 8.3+, in accordance with our <a href=\"https://contactform7.com/2025/12/02/wordpress-support-policy-revised/\" data-type=\"link\" data-id=\"https://contactform7.com/2025/12/02/wordpress-support-policy-revised/\">WordPress support policy</a>. If you are using older versions, upgrading them is advised.</p>\n\n\n\n\n\n\n<h4 id=\"major-changes\" class=\"wp-block-heading\">Major changes made after 6.2-RC</h4>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Improves JavaScript coding used in admin screens.</li>\n\n\n\n<li>Fixes a case sensitivity bug in a SWV rule class name.</li>\n\n\n\n<li>Block Editor: Fixes a bug that &#8220;NaN&#8221; strings irrelevantly appear in the sidebar.</li>\n\n\n\n<li>SWV: Changes the schema version name to <code>SWV Core 2026-09-20</code>.</li>\n\n\n\n<li>Revises some help tab contents.</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">You can browse the complete list of changes on <a href=\"https://github.com/rocklobster-in/contact-form-7/compare/v6.1.7...v6.2.0\" data-type=\"link\" data-id=\"https://github.com/rocklobster-in/contact-form-7/compare/v6.1.7...v6.2.0\">GitHub</a>.</p>\n\n\n<p><strong>Requires:</strong> WordPress 7.1 or higher<br />\n<strong>Tested up to:</strong> WordPress 7.1.2</p>\n<p><strong><a href=\"https://wordpress.org/plugins/contact-form-7/\">&raquo; Download Contact Form 7 plugin from WordPress.org</a></strong></p>\n\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"92937\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:7;a:6:{s:4:\"data\";s:63:\"\n		\n		\n		\n		\n		\n				\n		\n		\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:36:\"Contact Form 7 6.2 Release Candidate\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:57:\"https://contactform7.com/2026/09/22/contact-form-7-62-rc/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 22 Sep 2026 07:42:56 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:3:{i:0;a:5:{s:4:\"data\";s:12:\"Announcement\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:8:\"Releases\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:2;a:5:{s:4:\"data\";s:3:\"SWV\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:33:\"https://contactform7.com/?p=92890\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:508:\"We will publish Contact Form 7 version 6.2 in a few weeks. This is a major update, so we are releasing a release candidate to let you test 6.2 in advance. Join the RC testing and, if you find any bugs, please report them in the support forum or, if you are familiar with GitHub, &#8230; <a href=\"https://contactform7.com/2026/09/22/contact-form-7-62-rc/\" class=\"more-link\">Continue reading <span class=\"screen-reader-text\">Contact Form 7 6.2 Release Candidate</span> <span class=\"meta-nav\">&#8594;</span></a>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Takayuki Miyoshi\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:3595:\"\n<p class=\"wp-block-paragraph\">We will publish Contact Form 7 version 6.2 in a few weeks. This is a major update, so we are releasing a release candidate to let you test 6.2 in advance. Join the RC testing and, if you find any bugs, please report them in the <a href=\"https://wordpress.org/support/plugin/contact-form-7/\">support forum</a> or, if you are familiar with GitHub, on our <a href=\"https://contactform7.com/contributing/#reporting-issues\">GitHub repository</a>. We plan to release 6.2 in early October.</p>\n\n\n\n<span id=\"more-92890\"></span>\n\n\n\n<p class=\"wp-block-paragraph\">Download 6.2-rc from the <a href=\"https://wordpress.org/plugins/contact-form-7/\">plugin page</a> (Go to the <a href=\"https://wordpress.org/plugins/contact-form-7/advanced/#:~:text=Previous%20Versions\"><strong>Previous Versions</strong></a> section, select 6.2-rc, and download). Contact Form 7 6.2 requires PHP 8.3+ and WordPress 7.1+.</p>\n\n\n\n\n\n\n<h4 id=\"swv-2\" class=\"wp-block-heading\">SWV 2</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Contact Form 7 6.2 bundles version 2 of Schema-Woven Validation. The major changes in SWV 2 are:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>The <a href=\"https://packagist.org/packages/rocklobsterinc/\" data-type=\"link\" data-id=\"https://packagist.org/packages/rocklobsterinc/\">Composer packages for PHP</a> are newly available.</li>\n\n\n\n<li>The scope name of the <a href=\"https://www.npmjs.com/package/@rocklobsterinc/swv\" data-type=\"link\" data-id=\"https://www.npmjs.com/package/@rocklobsterinc/swv\">npm packages</a> has changed from <code>@contactable</code> to <code>@rocklobsterinc</code>.</li>\n\n\n\n<li>We have redesigned SWV 2 as a lean collection of validation rules. Unnecessary gimmicks, such as middleware, have been dropped.</li>\n</ul>\n\n\n\n<h4 id=\"major-changes\" class=\"wp-block-heading\">Major changes</h4>\n\n\n\n<ul class=\"wp-block-list\">\n<li>SWV: Introduces Composer packages for PHP: SWV v2.0.7, FormDataTree v2.0.7, and Rock Lobster&#8217;s PHP function library v1.0.6</li>\n\n\n\n<li>SWV: Upgrades npm packages for JavaScript: SWV v2.1.2, FormDataTree v2.1.3, and Rock Lobster&#8217;s JS function library v1.0.5</li>\n\n\n\n<li>SWV: Updates the SWV Schema version to <code>Contact Form 7 SWV Schema 2026-09-20</code>.</li>\n\n\n\n<li>Admin: Adds the Dashboard submenu.</li>\n\n\n\n<li>Admin: Overhauls the list table in the Contact Forms menu screen.</li>\n\n\n\n<li>Admin: Hides the shortcodes in the contact form editor screen.</li>\n\n\n\n<li>Admin: Improves the Brevo tab panel in the contact form editor.</li>\n\n\n\n<li>Admin: Makes all external links in the editing screen <code>target=\"_blank\"</code>.</li>\n\n\n\n<li>Adds &#8220;Exit if accessed directly&#8221; logic to the begining of all PHP files.</li>\n\n\n\n<li>Drops the deprecated includes/shortcodes.php file.</li>\n\n\n\n<li>REST API: Returns the appropriate status code based on whether the requester is logged in.</li>\n\n\n\n<li>Special mail-tags: Applies allowlisting to user-related SMT names.</li>\n\n\n\n<li>Replaces <code>wp_check_invalid_utf8()</code> to <code>wp_scrub_utf8()</code>.</li>\n\n\n\n<li>Adds <code>readonly</code> and type declaration to object properties.</li>\n\n\n\n<li>Makes all link URLs to contactform7.com website not translatable.</li>\n\n\n\n<li>New action hook: <code>wpcf7_dashboard_setup</code></li>\n\n\n\n<li>New action hook: <code>wpcf7_manage_custom_column</code></li>\n\n\n\n<li>Raises the minimum required versions to WordPress 7.1 and PHP 8.3.</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">You can browse the complete list of changes on <a href=\"https://github.com/rocklobster-in/contact-form-7/compare/v6.1.7...v6.2.0-rc\">GitHub</a>.</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"92890\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:8;a:6:{s:4:\"data\";s:57:\"\n		\n		\n		\n		\n		\n				\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:20:\"Contact Form 7 6.1.7\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:55:\"https://contactform7.com/2026/08/17/contact-form-7-617/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 17 Aug 2026 04:15:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Releases\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:33:\"https://contactform7.com/?p=92833\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:218:\"Contact Form 7 version 6.1.7 is now available. This is a minor update release including some improvements. Contact Form 7 6.1.7 has been tested with WordPress 7.1. You can browse the complete list of changes on GitHub.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Takayuki Miyoshi\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:672:\"\n<p class=\"wp-block-paragraph\">Contact Form 7 version 6.1.7 is now available. This is a minor update release including some improvements. Contact Form 7 6.1.7 has been tested with WordPress 7.1.</p>\n\n\n\n<span id=\"more-92833\"></span>\n\n\n\n\n\n\n<p class=\"wp-block-paragraph\">You can browse the complete list of changes on <a href=\"https://github.com/rocklobster-in/contact-form-7/compare/v6.1.6...v6.1.7\">GitHub</a>.</p>\n\n\n<p><strong>Requires:</strong> WordPress 6.7 or higher<br />\n<strong>Tested up to:</strong> WordPress 7.1-RC3</p>\n<p><strong><a href=\"https://wordpress.org/plugins/contact-form-7/\">&raquo; Download Contact Form 7 plugin from WordPress.org</a></strong></p>\n\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"92833\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:9;a:6:{s:4:\"data\";s:57:\"\n		\n		\n		\n		\n		\n				\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:20:\"Contact Form 7 6.1.6\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:55:\"https://contactform7.com/2026/05/15/contact-form-7-616/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 15 May 2026 02:57:09 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Releases\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:33:\"https://contactform7.com/?p=92666\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:232:\"Contact Form 7 version 6.1.6 is now available. This is a minor update release including some improvements. Contact Form 7 6.1.6 has been tested with WordPress 7.0. Major changes You can browse the complete list of changes on GitHub.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Takayuki Miyoshi\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:873:\"\n<p class=\"wp-block-paragraph\">Contact Form 7 version 6.1.6 is now available. This is a minor update release including some improvements. Contact Form 7 6.1.6 has been tested with WordPress 7.0.</p>\n\n\n\n<span id=\"more-92666\"></span>\n\n\n\n\n\n\n<h4 class=\"wp-block-heading\" id=\"major-changes\">Major changes</h4>\n\n\n\n<ul class=\"wp-block-list\">\n<li>CSS: Sets the <code>word-break</code> property on the screen reader response element.</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">You can browse the complete list of changes on <a href=\"https://github.com/rocklobster-in/contact-form-7/compare/v6.1.5...v6.1.6\">GitHub</a>.</p>\n\n\n<p><strong>Requires:</strong> WordPress 6.7 or higher<br />\n<strong>Tested up to:</strong> WordPress 7.0-RC3</p>\n<p><strong><a href=\"https://wordpress.org/plugins/contact-form-7/\">&raquo; Download Contact Form 7 plugin from WordPress.org</a></strong></p>\n\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"92666\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}}s:27:\"http://www.w3.org/2005/Atom\";a:1:{s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:0:\"\";s:7:\"attribs\";a:1:{s:0:\"\";a:3:{s:4:\"href\";s:30:\"https://contactform7.com/feed/\";s:3:\"rel\";s:4:\"self\";s:4:\"type\";s:19:\"application/rss+xml\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:44:\"http://purl.org/rss/1.0/modules/syndication/\";a:2:{s:12:\"updatePeriod\";a:1:{i:0;a:5:{s:4:\"data\";s:9:\"\n	hourly	\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:15:\"updateFrequency\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"\n	1	\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:4:\"site\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"22636741\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}}}}}}}s:4:\"type\";i:128;s:7:\"headers\";a:24:{s:4:\"date\";s:29:\"Sun, 08 Nov 2026 11:16:05 GMT\";s:12:\"content-type\";s:34:\"application/rss+xml; charset=UTF-8\";s:14:\"x-kinsta-cache\";s:3:\"HIT\";s:10:\"set-cookie\";s:325:\"__cf_bm=ZD7fI3DnNj6hR_1YAe3AgE09rHtuAQRkR_wtXSyhSp8-1794136565.2036614-1.0.1.1-jZrjdnldYNiFQDPPQZdeNCccl_TzPPemKxKqt8WKQv.ZYrCKuq8G8eoYrXl3x1koNpQYrHLJ