(88, 1, '2026-11-07 06:00:58', '2026-11-07 06:00:58', '<!-- wp:paragraph -->\n<p>Selamt datang di WordPress. Ini adalah pos pertama Anda. Sunting atau hapus, kemudian mulai menulis!</p>\n<!-- /wp:paragraph -->', 'Halo dunia!', '', 'inherit', 'closed', 'closed', '', '1-revision-v1', '', '', '2026-11-07 06:00:58', '2026-11-07 06:00:58', '', 1, 'http://localhost:8080/literasi/?p=88', 0, 'revision', '', 0),
