-></div>\n<!-- /wp:query --></section>\n<!-- /wp:group --></main>\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"theme\":\"arneiron-lite\",\"tagName\":\"footer\"} /-->', 'Front Page (Latest Posts)', 'The front page while Settings > Reading shows your latest posts: a starter hero, feature cards and the latest posts. Replace the placeholder text with your own.', 'inherit', 'closed', 'closed', '', '112-revision-v1', '', '', '2026-11-07 15:08:59', '2026-11-07 15:08:59', '', 112, 'http://localhost:8080/literasi/?p=126', 0, 'revision', '', 0),
