(130, 1, '2026-11-07 15:28:15', '2026-11-07 15:28:15', '<!-- wp:spacer {\"height\":\"55px\"} -->\n<div style=\"height:55px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {\"className\":\"container\"} -->\n<div class=\"wp-block-columns container\"><!-- wp:column {\"className\":\"col-md-5\"} -->\n<div class=\"wp-block-column col-md-5\"><!-- wp:heading {\"className\":\"animated fadeIn\"} -->\n<h2 class=\"wp-block-heading animated fadeIn\">Jejak Digital</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"animated fadeInLeft\"} -->\n<p class=\"animated fadeInLeft\"><strong>Jejak digital</strong> adalah <mark>rekam jejak informasi atau data yang ditinggalkan seseorang saat menggunakan perangkat digital dan internet</mark>. Semua aktivitas daring Anda membentuk catatan yang dapat dilihat atau dilacak oleh pihak lain</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"className\":\"col-md-6 col-md-offset1\"} -->\n<div class=\"wp-block-column col-md-6 col-md-offset1\"><!-- wp:image {\"id\":109,\"aspectRatio\":\"1.400437636761488\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"animated fadeInUp is-style-rounded\",\"anchor\":\"wp-block-themeisle-blocks-image-99c9e23a\",\"boxShadow\":true,\"boxShadowColor\":\"#ff2a2a\",\"boxShadowColorOpacity\":84,\"boxShadowHorizontal\":24,\"boxShadowVertical\":18} -->\n<figure class=\"wp-block-image size-full animated fadeInUp is-style-rounded\" id=\"wp-block-themeisle-blocks-image-99c9e23a\"><img src=\"http://localhost:8080/literasi/wp-content/uploads/2026/11/pexels-peaky-31177054.jpg\" alt=\"Digital\" class=\"wp-image-109\" style=\"aspect-ratio:1.400437636761488\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->', 'Pengertian Jejak Digitakl', '', 'inherit', 'closed', 'closed', '', '73-revision-v1', '', '', '2026-11-07 15:28:15', '2026-11-07 15:28:15', '', 73, 'http://localhost:8080/literasi/?p=130',